<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue';
import {researchPackLimit,type ResearchFile,type ResearchPreview,type ResearchRow} from '../shared/catalog-research';
const props=defineProps<{selectedIds:string[];filteredIds:string[]}>();
const emit=defineEmits<{reload:[];notify:[message:string]}>();
const open=ref(false),busy=ref(false),error=ref(''),file=ref<File|null>(null),packet=ref<ResearchFile|null>(null),preview=ref<ResearchPreview|null>(null),selection=ref<string[]>([]);
let opener:HTMLElement|undefined;
const headers=[{title:'Component / field',key:'field'},{title:'Current',key:'before',sortable:false},{title:'Proposed changes',key:'after',sortable:false},{title:'Result',key:'status'},{title:'Source and evidence',key:'evidence',sortable:false}];
const rows=computed(()=>preview.value?.rows.map(row=>({...row,selectable:row.status==='Fill'}))||[]);
const fingerprint=(keys:string[])=>JSON.stringify([...keys].sort());
const reviewed=computed(()=>!!preview.value&&fingerprint(selection.value)===fingerprint(preview.value.selected));
const ready=computed(()=>!busy.value&&preview.value?.valid&&reviewed.value&&selection.value.length>0);
function hasUnsavedChanges(){return busy.value||open.value&&!!file.value;}
function confirmDiscard(){if(busy.value)return false;if(open.value&&file.value&&!window.confirm('Discard imported research proposals?'))return false;open.value=false;file.value=null;return true;}
defineExpose({hasUnsavedChanges,confirmDiscard});
watch(file,()=>{packet.value=null;preview.value=null;selection.value=[];error.value='';});
async function call(url:string,body:unknown,revision?:string){const r=await fetch(url,{method:revision?'PUT':'POST',headers:{'Content-Type':'application/json',...(revision?{'If-Match':revision}:{})},body:JSON.stringify(body)}),result=await r.json();if(!r.ok)throw Error(result.error||'Research request failed');return result;}
async function exportPack(ids:string[]){if(busy.value||!ids.length||ids.length>researchPackLimit)return;busy.value=true;error.value='';try{const result=await call('/api/catalog/research/export',{componentIds:ids}),blob=new Blob([JSON.stringify(result,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='component-research.json';document.body.append(a);a.click();a.remove();window.setTimeout(()=>URL.revokeObjectURL(url),1000);emit('notify',`Exported ${ids.length} components for research.`);}catch(reason){error.value=reason instanceof Error?reason.message:String(reason);}finally{busy.value=false;}}
function begin(){if(busy.value)return;opener=document.activeElement instanceof HTMLElement?document.activeElement:undefined;file.value=null;preview.value=null;error.value='';open.value=true;}
async function readFile(){if(busy.value||!file.value)return;busy.value=true;error.value='';try{if(file.value.size>8*1024*1024)throw Error('Use a research JSON file no larger than 8 MiB.');packet.value=JSON.parse(await file.value.text());await updatePreview(true);}catch(reason){error.value=reason instanceof Error?reason.message:String(reason);}finally{busy.value=false;}}
async function updatePreview(initial=false){if(!packet.value)return;const result=await call('/api/catalog/research/preview',{file:packet.value,...(!initial?{selected:selection.value}:{})});preview.value=result;selection.value=[...result.selected];}
async function refresh(){if(busy.value)return;busy.value=true;error.value='';try{await updatePreview();}catch(reason){preview.value=null;error.value=reason instanceof Error?reason.message:String(reason);}finally{busy.value=false;}}
async function apply(){if(!ready.value||!packet.value||!preview.value)return;const reviewed=preview.value;busy.value=true;error.value='';try{const result=await call('/api/catalog/research/apply',{file:packet.value,selected:reviewed.selected,token:reviewed.token},reviewed.revision);open.value=false;file.value=null;emit('reload');emit('notify',`Applied ${result.fields} proposals on ${result.components} components. Source evidence saved; components need verification.`);}catch(reason){preview.value=null;error.value=reason instanceof Error?reason.message:String(reason);}finally{busy.value=false;}}
const display=(value:unknown)=>value===undefined?'Unknown':typeof value==='string'?value:JSON.stringify(value,null,2);
function source(row:ResearchRow){try{const url=new URL(row.sourceUrl);return ['http:','https:'].includes(url.protocol)&&!url.username&&!url.password?url.href:'';}catch{return '';}}
function restoreFocus(){void nextTick(()=>{if(opener?.isConnected)opener.focus();else document.getElementById('main-content')?.focus();});}
</script>
<template>
<section class="panel build-notes control-stack"><h2>Research handoff</h2><p>Export a JSON research pack for an agent. It includes existing data, missing fields and instructions. Have the agent fill proposals with source URLs and evidence, then import the returned file here. Fill missing fields or merge named ports, PCIe slots, lane rules, fans/pumps, cooling headers and shared current budgets by stable ID. Known properties and omitted records are preserved; updated components need verification.</p><div class="d-flex flex-wrap ga-3"><v-btn variant="outlined" :disabled="busy||!selectedIds.length||selectedIds.length>researchPackLimit" @click="exportPack([...selectedIds])">Export selected research pack ({{selectedIds.length}})</v-btn><v-btn variant="outlined" :disabled="busy||!filteredIds.length||filteredIds.length>researchPackLimit" @click="exportPack([...filteredIds])">Export filtered research pack ({{filteredIds.length}})</v-btn><v-btn color="primary" :disabled="busy" @click="begin">Import research updates</v-btn></div><p class="form-hint">Filtered export includes every matching row, across pages. Selected export includes hidden selections. Up to {{researchPackLimit}} components per pack.</p><v-alert v-if="error&&!open" type="error" role="alert">{{error}}</v-alert></section>
<v-dialog :model-value="open" :open-on-click="false" :activator="opener" persistent scrollable max-width="1200" aria-labelledby="research-import-title" @keydown.esc.stop.prevent="confirmDiscard" @after-leave="restoreFocus"><v-card class="editor-dialog"><v-card-title class="dialog-head"><h2 id="research-import-title">Review research updates</h2></v-card-title><v-card-text class="dialog-body" :inert="busy"><v-alert v-if="error" type="error" role="alert">{{error}}</v-alert><p>Choose the returned research JSON file. Existing values, component identities and verification are protected. For named collections, Proposed changes shows only new records and properties to fill. Collections add records and fill unknown properties by ID; a conflicting property withholds the whole collection. Select the valid proposals you want to apply; conflicts and invalid entries are kept out of the selection. Source URLs are recorded without fetching them.</p><v-file-input v-model="file" label="Research JSON file (8 MiB maximum)" accept=".json,application/json" :disabled="busy" /><v-btn variant="outlined" :disabled="busy||!file" :loading="busy" @click="readFile">Read and preview file</v-btn>
<template v-if="preview"><h3>Review {{preview.rows.length}} proposed values</h3><p role="status">{{preview.fields}} fields on {{preview.components}} components reviewed · {{preview.rows.filter(row=>row.status==='Conflict').length}} conflicts kept · {{preview.rows.filter(row=>row.status==='Invalid').length}} invalid proposals excluded · {{preview.blank}} blank proposals ignored.</p><v-alert v-if="!preview.valid" type="error" role="alert">{{preview.error}}</v-alert><v-alert v-if="!reviewed" type="info" role="status">Selection changed. Update the preview before applying.</v-alert><div class="d-flex flex-wrap ga-3"><v-btn variant="text" :disabled="busy" @click="selection=rows.filter(row=>row.selectable).map(row=>row.key)">Select all fillable proposals</v-btn><v-btn variant="text" :disabled="busy" @click="selection=[]">Clear selection</v-btn><v-btn variant="outlined" :disabled="busy" @click="refresh">Update preview</v-btn></div>
<v-data-table v-table-scroll v-model="selection" :items="rows" :headers="headers" item-value="key" item-selectable="selectable" show-select select-strategy="page" :items-per-page="25" :items-per-page-options="[10,25,50,100]" :mobile="false"><template #caption><caption class="sr-only">Research proposals, current values, evidence and conflict results</caption></template><template #item.data-table-select="{item}"><v-checkbox-btn :model-value="selection.includes(item.key)" :disabled="busy||!item.selectable" :aria-label="`Apply ${item.name}: ${item.field}`" @update:model-value="value=>selection=value?[...new Set([...selection,item.key])]:selection.filter(key=>key!==item.key)" /></template><template #item.field="{item}"><strong>{{item.name}}</strong><small>{{item.field}}</small></template><template #item.before="{item}"><pre class="research-value">{{display(item.before)}}</pre></template><template #item.after="{item}"><pre class="research-value">{{display(item.changes??item.after)}}</pre></template><template #item.status="{item}"><strong>{{item.status}}</strong><p>{{item.reason}}</p></template><template #item.evidence="{item}"><a v-if="source(item)" :href="source(item)" target="_blank" rel="noopener noreferrer">Source documentation</a><p v-else>{{item.sourceUrl}}</p><p>{{item.evidence}}</p></template></v-data-table><p v-if="!preview.rows.length">No proposed values were filled in. Ask the agent to update the proposals in the exported file; existing data is context only.</p></template>
</v-card-text><v-card-actions class="dialog-footer"><v-btn variant="text" :disabled="busy" @click="confirmDiscard">Cancel</v-btn><v-spacer /><v-btn color="primary" :disabled="!ready" :loading="busy" @click="apply">Apply {{selection.length}} selected proposals</v-btn></v-card-actions></v-card></v-dialog>
</template>
<style scoped>.research-value{white-space:pre-wrap;overflow-wrap:anywhere;max-width:260px;max-height:180px;overflow:auto;font:inherit}.research-value+*{margin-top:8px}</style>
